/**
 * Every sprite the game uses. Each key maps to `public/assets/sprites/<key>.svg`.
 * `w` × `h` is the native size in world units (w = along the facing direction).
 * All vehicle/projectile sprites face EAST (+x) at rotation 0, drawn top-down.
 * Art direction (v1): bold, readable units at ~2× real scale with thick dark outlines and flat
 * cel-shaded fills — crimson/red accents for enemies, steel blue/white for friendlies — over muted,
 * detailed desert terrain; a credible military look with light sci-fi flavour (mechs), not toy-like.
 * Generated by `node scripts/art/index.mjs`.
 */
export interface SpriteSpec {
  w: number;
  h: number;
  note: string;
}

